CREATE OR REPLACE FUNCTION public.validate_sync_draft() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.amount_type = 'FIXED' AND (NEW.amount IS NULL OR NEW.amount <= 0 OR NEW.max_cap IS NOT NULL) THEN RAISE EXCEPTION 'Enter a positive fixed amount'; END IF; IF NEW.amount_type = 'VARIABLE' AND (NEW.amount IS NOT NULL OR (NEW.max_cap IS NOT NULL AND NEW.max_cap <= 0)) THEN RAISE EXCEPTION 'Variable requests require an optional positive cap and no fixed amount'; END IF; IF current_user IN ('authenticated','anon') THEN IF TG_OP = 'INSERT' AND NEW.status <> 'DRAFT' THEN RAISE EXCEPTION 'Payment connection required to activate a request'; END IF; IF TG_OP = 'UPDATE' AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.last_at IS DISTINCT FROM OLD.last_at OR NEW.approved_at IS DISTINCT FROM OLD.approved_at) THEN RAISE EXCEPTION 'Only the payment service can change execution state'; END IF; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.validate_transaction_sync_owner() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.sync_request_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.sync_requests WHERE id=NEW.sync_request_id AND user_id=NEW.user_id) THEN RAISE EXCEPTION 'Sync request must belong to the transaction owner'; END IF; RETURN NEW; END $$;
CREATE TRIGGER transactions_sync_owner BEFORE INSERT OR UPDATE ON public.transactions FOR EACH ROW EXECUTE FUNCTION public.validate_transaction_sync_owner();